function q({registerIndicator:K,nulls:m}){K({id:"oa-kvo",name:"Klinger Volume Oscillator (KVO)",category:"Volume",placement:"pane",inputs:[{key:"fastPeriod",type:"number",label:"Fast EMA Period",default:34,min:1,max:5e3,step:1},{key:"slowPeriod",type:"number",label:"Slow EMA Period",default:55,min:1,max:5e3,step:1},{key:"signalPeriod",type:"number",label:"Signal Line Period",default:13,min:1,max:5e3,step:1}],plots:[{key:"kvo",type:"line",title:"KVO",style:{color:"#ffeb3b",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#2962ff",lineWidth:1}},{key:"histogram",type:"histogram",title:"Histogram",style:{color:"#26a69a"},colorBy:({value:n})=>n>=0?"#26a69a":"#ef5350"}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],calc(n,f){const H=Math.max(1,Math.floor(Number(f.fastPeriod)||34)),W=Math.max(1,Math.floor(Number(f.slowPeriod)||55)),B=Math.max(1,Math.floor(Number(f.signalPeriod)||13)),s=n.length,v=2/(H+1),w=2/(W+1),S=2/(B+1),k=new Array(s).fill(NaN),P=new Array(s).fill(NaN),F=new Array(s).fill(NaN);let h=1,u=NaN,g=!0,M=1,L=1,d=1,t=0,l=0,o=0;for(let e=0;e<s;e++){const a=n[e],x=a.high,p=a.low,V=a.close,r=(x+p+V)/3,O=Number.isFinite(u)?u:r;r>O?h=1:r<O&&(h=-1),u=r;const y=x-p,R=y>0?Math.abs(2*((y-(V-p))/y)-1):0,Z=Number.isFinite(a.volume)?a.volume:0,A=h*Z*R;t=v*(A-t)+t,l=w*(A-l)+l;let b,N;if(g){M*=1-v,L*=1-w;const E=1/(1-M),j=1/(1-L);b=E*t,N=j*l,g=d>1e-10}else b=t,N=l;const c=b-N;let i;o=S*(c-o)+o,g?(d*=1-S,i=1/(1-d)*o):i=o,!(!Number.isFinite(c)||!Number.isFinite(i))&&(k[e]=c,P[e]=i,F[e]=c-i)}return{kvo:m(k),signal:m(P),histogram:m(F)}}})}export{q as default};
